mapper.update:
update collection
list_type = #{listType}, progress = #{progress}, favorite = #{favorite},
where id = #{id}

mapper.select:
select c.id, c.user_id, c.anime_id, c.list_type, c.progress, c.favorite, c.created_at, c.updated_at, a.title, a.cover from collection c left join anime a on c.anime_id = a.id
c.user_id = #{userId}
and c.list_type = #{listType}
order by c.id desc
